// Frozen scores, original ordinal as the stable tie breaker. No hidden-state input.
struct StableIndexLess {
 const std::vector<ScoredMove>* scores;
 bool operator()(uint16_t a,uint16_t b) const {
  const double x=(*scores)[a].score,y=(*scores)[b].score;
  return x<y||(x==y&&a>b);
 }
};
bool prepareStableIndexHeap(const std::vector<ScoredMove>& scores,std::vector<uint16_t>& indices){
 indices.clear();if(scores.size()>std::numeric_limits<uint16_t>::max())return false;
 indices.resize(scores.size());for(size_t i=0;i<indices.size();i++)indices[i]=uint16_t(i);
 std::make_heap(indices.begin(),indices.end(),StableIndexLess{&scores});return true;
}
Move popStableIndexHeap(const std::vector<ScoredMove>& scores,std::vector<uint16_t>& indices){
 if(indices.empty())throw std::logic_error("empty stable index heap");
 std::pop_heap(indices.begin(),indices.end(),StableIndexLess{&scores});
 const uint16_t i=indices.back();indices.pop_back();return scores[i].move;
}

